export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
	schelfLibrary: (callback: (payload: Finished) => void) => listen<Finished>("schelf.library", callback),
	schelfOperations: (callback: (payload: Operation[]) => void) => listen<Operation[]>("schelf.operations", callback),
};

export type Action = "install" | "remove" | "update";

export type AddedSource = {
	file: string,
	name: string,
	url: string,
	packages: string[],
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	files: string[],
	page: string | null,
} & Appearance;

export type AppUpdate = {
	key: string,
	source: Source,
	id: string,
	desktop: string | null,
	name: string,
	icon: string | null,
	from: string | null,
	to: string | null,
	size: number,
	platform: boolean,
	installation: Installation | null,
	reference: string | null,
	package: string | null,
	store: StoreUpdate | null,
};

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

/**  Why an app or one of its versions was pulled or flagged. */
export type Block = {
	action: Severity,
	reason: string,
	note: string | null,
};

export type Builder = "github-actions" | "developer";

/**  What the pages show of an entry. */
export type CatalogApp = {
	id: string,
	kind: Kind,
	origin: Origin,
	name: string,
	summary: string,
	icon: string | null,
	/**  An extension's wide picture, cut from its first screenshot. */
	art: string | null,
	developer: string | null,
	package: string | null,
};

/**  A repository and what the system said about it, to be trusted before it's added. */
export type CheckedSource = {
	draft: RepositoryDraft,
	described: Described,
	added: boolean,
};

export type Collection = "popular" | "updated";

/**  What you saw and agreed to before installing or updating a store app. */
export type Consent = {
	version: string,
	permissions: Declared | null,
	extension: ExtensionAccess | null,
	fullAccess: boolean,
};

export type Corners = "rounded" | "square";

export type CustomIcons = {
	icon: boolean,
	symbolic: boolean,
};

/**
 *  What an app may use, in Luft's shared permission format; an app that
 *  declares nothing gets full access.
 */
export type Declared = {
	network: boolean,
	filesystems: string[],
	devices: string[],
	talk: string[],
	unsandboxed: string | null,
};

/**
 *  What the system says about a draft: the sources in it and the keys their packages must be
 *  signed with.
 */
export type Described = {
	file: string,
	sources: DescribedSource[],
	keys: SourceKey[],
};

export type DescribedSource = {
	id: string,
	name: string,
	url: string,
};

/**  A file to download for an app this computer can't install itself. */
export type Download = {
	url: string,
	name: string,
	size: number,
};

/**
 *  What an extension asks for: permissions from the extension API, and
 *  whether it runs a program of its own.
 */
export type ExtensionAccess = {
	permissions: string[],
	helper: boolean,
};

/**  A Fedora package's page, from Fedora's software sources. */
export type FedoraDetails = {
	version: string,
	description: string,
	license: string,
	homepage: string | null,
	size: number,
	download: number,
};

export type Finished = {
	keys: string[],
	action: Action,
	succeeded: boolean,
};

/**  How Luft installs a store app, and so how it updates and removes it. */
export type Format = "sabine" | "appimage" | "luft-extension";

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type Installation = "user" | "system";

export type InstalledApp = {
	key: string,
	source: Source,
	id: string,
	desktop: string | null,
	name: string,
	summary: string | null,
	icon: string | null,
	version: string | null,
	size: number,
	origin: string,
	installation: Installation | null,
	reference: string | null,
	package: string | null,
	path: string | null,
	commands: string[],
	services: string[],
	/**  The schelf.store app it was installed as. */
	listing: string | null,
};

/**  A store app or extension on this computer. */
export type InstalledFromStore = {
	id: string,
	kind: Kind,
	name: string,
	version: string,
	local: string,
	block: Block | null,
};

export type Job = { kind: "installFlathub"; id: string } | { kind: "installStore"; id: string; consent: Consent } | { kind: "updateStore"; id: string; consent: Consent } | { kind: "removeStore"; id: string } | { kind: "installFlatpakRef"; path: string } | { kind: "installFlatpakBundle"; path: string } | { kind: "installDeb"; path: string } | { kind: "removeDeb"; package: string } | { kind: "updateDebs"; packages: string[] } | { kind: "addFlatpakRepo"; path: string; name: string } | { kind: "installAppImage"; path: string; 
/**  Whether you let an app that asks to run unsandboxed do so. */
fullAccess: boolean } | { kind: "installTool"; package: string } | { kind: "installToolFile"; path: string } | { kind: "removeFlatpak"; installation: Installation; reference: string } | { kind: "removeAppImage"; id: string } | { kind: "removeTool"; package: string } | { kind: "updateFlatpaks"; installation: Installation; references: string[] } | { kind: "updateAppImage"; id: string } | { kind: "updateTools"; packages: string[] } | { kind: "installSystemPackages"; packages: string[] } | { kind: "removeSystemPackages"; packages: string[] } | { kind: "installSystemPackageFile"; path: string; package: string; repository?: RepositoryDraft | null } | { kind: "removeRepository"; file: string };

export type Kind = "app" | "extension";

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Motion = "full" | "reduced" | "off";

export type Names = {
	own: string,
	custom: string | null,
};

export type Notifications = {
	allowed: boolean,
	banners: boolean,
	lockScreen: boolean,
	detailsOnLockScreen: boolean,
	shownOnLockScreen: boolean,
	sound: string,
	duringDoNotDisturb: string,
	keptInList: boolean,
};

/**  The same app on Flathub, which installs better than a `.deb` file can. */
export type OnFlathub = {
	id: string,
	name: string,
	summary: string | null,
	icon: string | null,
	verified: boolean,
};

export type OpenedFile = { kind: "flatpakRef"; path: string; id: string; title: string; branch: string | null; url: string; runtime: boolean; summary: string | null; homepage: string | null; icon: string | null } | { kind: "flatpakBundle"; path: string; id: string; title: string; branch: string; summary: string | null; icon: string | null; size: number; runtime: string | null; origin: string | null } | { kind: "flatpakRepo"; path: string; name: string; title: string; url: string; summary: string | null; homepage: string | null } | { kind: "package"; path: string; package: string; version: string; summary: string; description: string; license: string; homepage: string | null; size: number; installed: boolean; system: boolean; desktop: string | null; repository: CheckedSource | null; repositoryError: string | null; verified: boolean } | { kind: "deb"; path: string; package: string; name: string; version: string; summary: string; description: string; homepage: string | null; size: number; icon: string | null; installed: boolean; runsHere: boolean; flathub: OnFlathub | null } | { kind: "appImage"; path: string; name: string; summary: string | null; version: string | null; icon: string | null; size: number; 
/**  What it declared it needs, for a Sabine app. */
permissions: Permissions | null; 
/**  Why it asks to run outside a sandbox, when it does. */
unsandboxed: string | null };

export type Operation = {
	id: number,
	key: string,
	members: string[],
	title: string,
	action: Action,
	state: OperationState,
	progress: Progress | null,
	error: string | null,
};

export type OperationState = "queued" | "running" | "failed";

export type Origin = "schelf" | "flathub" | "fedora";

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type Permissions = {
	shared: string[],
	sockets: string[],
	devices: string[],
	filesystems: string[],
	sessionBus: string[],
	systemBus: string[],
};

export type Progress = {
	stage: Stage,
	fraction: number | null,
};

/**  Where a release came from. */
export type Provenance = {
	origin: Builder,
	repository: string | null,
	commit: string | null,
	run: string | null,
};

/**  The listed app that took a delisted one's place, and why. */
export type ReplacedBy = {
	app: CatalogApp,
	note: string,
};

/**
 *  A repository file and the keys it names, by the address `gpgkey` gives each, ready to be
 *  checked and added.
 */
export type RepositoryDraft = {
	file: string,
	text: string,
	keys: { [key in string]: string },
};

/**
 *  What an installed AppImage's sandbox opens to it, and why it asked to run
 *  without one, if it did.
 */
export type Sandbox = {
	permissions: Permissions,
	unsandboxed: string | null,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Screenshot = {
	url: string,
	caption: string | null,
};

export type Setting = { setting: "allowed"; value: boolean } | { setting: "banners"; value: boolean } | { setting: "lockScreen"; value: boolean } | { setting: "detailsOnLockScreen"; value: boolean } | { setting: "sound"; value: string } | { setting: "duringDoNotDisturb"; value: string } | { setting: "keptInList"; value: boolean };

export type Severity = "block" | "warn";

export type Source = "flatpak" | "appImage" | "tool" | "debian" | "system" | "sabine" | "extension";

export type SourceKey = {
	fingerprint: string,
	user: string,
};

export type Stage = "waiting" | "preparing" | "downloading" | "installing" | "removing" | "finishing";

/**  A store app's page, for the channel you follow. */
export type StoreDetails = {
	id: string,
	kind: Kind,
	/**  How it installs here; none when there's only a file to download. */
	installer: Format | null,
	name: string,
	summary: string,
	description: string,
	icon: string | null,
	screenshots: Screenshot[],
	developer: string,
	verified: boolean,
	homepage: string | null,
	license: string | null,
	channel: string,
	channels: string[],
	version: string | null,
	published: string | null,
	notes: string,
	size: number | null,
	download: Download | null,
	declared: Declared | null,
	extension: ExtensionAccess | null,
	access: Permissions | null,
	provenance: Provenance | null,
	/**
	 *  Whether its publisher took it off schelf.store, which offers no
	 *  releases of it any more. A copy you have keeps working.
	 */
	withdrawn: boolean,
	replacedBy: ReplacedBy | null,
};

export type StoreState = {
	installed: InstalledFromStore[],
	outOfDate: boolean,
};

/**  A newer release of a store app than the one installed. */
export type StoreUpdate = {
	id: string,
	kind: Kind,
	format: Format,
	name: string,
	icon: string | null,
	local: string,
	from: string,
	to: string,
	size: number,
	consent: Consent,
	/**  Whether it asks for more than you agreed to, so it waits for you. */
	widens: boolean,
	/**
	 *  The name of the app that took this one's place, which the update
	 *  moves you to.
	 */
	replacement: string | null,
};

export type ToolSummary = {
	package: string,
	summary: string,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Updates = {
	apps: AppUpdate[],
	checked: number,
	error: string | null,
};
